// Visual editorial por área: apenas decorativo; nunca substitui o texto da tarefa.
function artKey(t){
 const s=((t.title||'')+' '+(t.room||'')).toLocaleLowerCase('pt-PT');
 if(/gato|planta tóxica|plantas potencialmente/.test(s))return 'botanical';
 if(/sifão|canaliza|odor|cheiro|esgoto|torneira|lava-loiça|poço/.test(s))return 'plumbing';
 if(/eletric|cctv|câmara|videoporteiro|cabo|quadro|luminária|iluminação/.test(s))return 'electric';
 if(/jardim|terreno|alpendre|terraço|limoeiro|mato|árvore|raiz/.test(s))return 'outdoor';
 if(/lavandaria|roupa|estendal|cordas/.test(s))return 'laundry';
 if(/cozinha|café|bebidas|louça/.test(s))return 'coffee';
 if(/wc |banho|duche|lavatório|piaçaba|higiénico/.test(s))return 'bath';
 if(/escritório|secretária|impressora|monitor|cadeira/.test(s))return 'office';
 if(/limpeza|aspirador|limpar|pó|chão/.test(s))return 'cleaning';
 if(/caixote|armário|arrumar|organiza|móvel|rodapé|guardar/.test(s))return 'storage';
 return 'general';
}
const roomIcons={"Cozinha":"coffee","Exterior":"outdoor","Instalações técnicas":"electric","Lavandaria":"laundry","Escritório":"office","Organização geral":"storage","WC completo":"bath","WC suite":"bath","WC escritório":"bath","WC serviço":"bath","Sala":"coffee","Segurança":"botanical","Administração":"storage"};
// Ilustração de cada divisão a partir do nome (a ordem importa: «WC Quarto Principal» é um WC, não um quarto).
function roomArt(room){const r=String(room||'').toLocaleLowerCase('pt-PT');
 const rules=[[/wc.*(principal|suite|suíte)|duche/,'wc-duche'],[/wc.*servi|lavabo/,'plumbing'],[/^wc|casa de banho|banho/,'bath'],[/nascente/,'quarto-nascente'],[/poente/,'quarto-poente'],[/quarto/,'quarto-principal'],[/sala/,'sala'],[/cozinha/,'coffee'],[/lavandaria/,'laundry'],[/alpendre|varanda|pátio|patio/,'alpendre'],[/hall|entrada|vestíbulo/,'hall'],[/corredor|escada/,'corredor'],[/terraço|terraco|cobertura|rooftop/,'terraco'],[/jardim|exterior|quintal/,'outdoor'],[/escritório|escritorio/,'office'],[/garagem/,'garagem'],[/arrumo|organiza|despensa|sótão|sotao|cave/,'storage'],[/técnic|tecnic|quadro/,'electric']];
 for(const [re,k] of rules)if(re.test(r))return k;return 'general';}
// Pisos: lista em settings.floors e piso de cada divisão em settings.roomFloors.
const floorOf=r=>config().roomFloors[r]||'';
const roomShort=r=>String(r||'').replace(/\s*\((piso|Piso)\s[^)]*\)\s*$/,'');
function roomsByFloor(list){const fl=config().floors;const groups=fl.map(f=>({floor:f,rooms:list.filter(r=>floorOf(r)===f)}));const rest=list.filter(r=>!fl.includes(floorOf(r)));if(rest.length)groups.push({floor:fl.length?'Sem piso':'',rooms:rest});return groups.filter(g=>g.rooms.length);}
function roomOptions(list,selected){const groups=roomsByFloor(list);if(groups.length===1&&!groups[0].floor)return list.map(r=>option(r,r,selected)).join('');return groups.map(g=>`<optgroup label="${esc(g.floor)}">${g.rooms.map(r=>option(r,roomShort(r),selected)).join('')}</optgroup>`).join('');}
function visualRooms(active){
 const counts={};active.forEach(t=>{const r=t.room||'Geral';counts[r]=(counts[r]||0)+1;});
 const order=config().rooms;const fl=config().floors;const rank=r=>{const f=fl.indexOf(floorOf(r));const i=order.indexOf(r);return (f<0?99:f)*1000+(i<0?999:i);};
 const names=Object.keys(counts).sort((a,b)=>rank(a)-rank(b)||counts[b]-counts[a]).slice(0,8);
 return names.map(room=>`<button class="room-tile" type="button" data-action="open-room" data-room="${esc(room)}"><span class="room-art art-${esc(roomArt(room))}" aria-hidden="true"></span><span class="room-tile-meta"><strong>${esc(roomShort(room))}</strong><small>${floorOf(room)?esc(floorOf(room))+' · ':''}${counts[room]} ${counts[room]===1?'tarefa':'tarefas'}</small></span><span class="room-arrow" aria-hidden="true">↗</span></button>`).join('');
}
