// Confirmação curta e centrada (substitui o confirm() do browser, que nalgumas apps é bloqueado ou pouco legível).
function confirmDialog({title,message='',confirmLabel='Confirmar',cancelLabel='Cancelar',danger=false}){return new Promise(resolve=>{
 document.getElementById('confirm-holder')?.remove();const prev=document.activeElement;
 const holder=document.createElement('div');holder.id='confirm-holder';
 holder.innerHTML=`<div class="confirm-overlay"><div class="confirm-box" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title" aria-describedby="confirm-msg"><h2 id="confirm-title">${esc(title)}</h2>${message?`<p id="confirm-msg">${esc(message)}</p>`:''}<div class="confirm-actions"><button type="button" class="button" data-confirm="no">${esc(cancelLabel)}</button><button type="button" class="button ${danger?'danger-solid':'primary'}" data-confirm="yes">${esc(confirmLabel)}</button></div></div></div>`;
 document.body.appendChild(holder);
 const done=v=>{holder.remove();document.removeEventListener('keydown',onKey,true);try{prev?.focus();}catch{}resolve(v);};
 const onKey=e=>{if(e.key==='Escape'){e.stopPropagation();done(false);}if(e.key==='Tab'){const b=[...holder.querySelectorAll('button')];const i=b.indexOf(document.activeElement);e.preventDefault();b[(i+(e.shiftKey?-1:1)+b.length)%b.length].focus();}};
 document.addEventListener('keydown',onKey,true);
 holder.addEventListener('click',e=>{const b=e.target.closest('[data-confirm]');if(b){e.stopPropagation();done(b.dataset.confirm==='yes');return;}if(e.target.classList.contains('confirm-overlay'))done(false);});
 holder.querySelector('[data-confirm="no"]').focus();
});}
