function demoApi(p,method,b){if(p==='/api/bootstrap')return {setup:false,user:store.user};{const fx=demoFeatureApi(p,method,b);if(fx!==undefined)return fx;const ff=demoFinanceApi(p,method,b);if(ff!==undefined)return ff;}{const m=p.match(/^\/api\/people\/([^/]+)\/(status|schedule)$/);if(m&&method==='PATCH'){const u=store.people.find(x=>x.id===m[1]);if(!u)throw Error('Pessoa não encontrada.');if(m[2]==='status'){if(u.id===store.user.id)throw Error('Não podes desativar a tua própria conta.');u.active=b.active;let n=0;store.tasks.forEach(t=>{if(!b.active&&t.assignedTo===u.id&&t.status!=='done'){t.assignedTo=null;t.unassignedFrom=u.id;n++;}else if(b.active&&t.unassignedFrom===u.id){if(!t.assignedTo&&t.status!=='done'){t.assignedTo=u.id;n++;}delete t.unassignedFrom;}});persistDemo();return {people:store.people,tasks:n};}else u.accessDays=b.accessDays;persistDemo();return {people:store.people};}}if(p==='/api/me'&&method==='PATCH'){const u=store.people.find(x=>x.id===store.user.id)||store.user;if('name'in b){const n=String(b.name||'').trim();if(n.length<2)throw Error('O nome deve ter pelo menos 2 caracteres.');u.name=n;store.user.name=n;}if('photo'in b)u.photo=b.photo||'';persistDemo();return {user:store.user,people:store.people};}if(p==='/api/state')return store;
 if(p==='/api/logout')return {ok:true};if(p==='/api/settings'&&method==='PATCH'){store.settings=b;persistDemo();return {settings:b};}if(p==='/api/export')return store;if(p==='/api/shopping'&&method==='POST'){const item={...b,id:'si'+Date.now(),purchased:false,createdBy:store.user.id};store.shopping=shopping().concat(item);persistDemo();return {item};}const sm=p.match(/^\/api\/shopping\/([^/]+)$/);if(sm){const it=shopping().find(x=>x.id===sm[1]);if(method==='PATCH'&&it)Object.assign(it,b);if(method==='DELETE')store.shopping=shopping().filter(x=>x.id!==sm[1]);persistDemo();return {item:it};}if(p==='/api/worklogs'&&method==='POST'){const entry={...b,id:'wl'+Date.now(),userId:b.userId||store.user.id};store.workLogs=workLogs().concat(entry);persistDemo();return {entry};}
 if(p==='/api/tasks'&&method==='POST'){const t={id:'d'+Date.now()+Math.random().toString().slice(2),createdAt:new Date().toISOString(),...b};store.tasks.push(t);persistDemo();return {task:t};}
 const m=p.match(/^\/api\/tasks\/([^/]+)(\/complete)?$/);if(m){let t=tasks().find(x=>x.id===m[1]);if(!t)throw Error('Tarefa não encontrada.');if(m[2]){store.history.push({id:'h'+Date.now(),title:t.title,at:new Date().toISOString(),by:store.user.id,kind:t.kind,assignedTo:t.assignedTo});if(t.kind==='routine'&&t.repeat!=='none'){t.status='todo';t.dueDate=nextDemoDate(t.dueDate,t.repeat);t.suggested=false;if(Array.isArray(t.rotation)&&t.rotation.length>1){const i=t.rotation.indexOf(t.assignedTo);t.assignedTo=t.rotation[(i+1)%t.rotation.length];}}else t.status='done';}else if(method==='PATCH'){Object.assign(t,b);}else if(method==='DELETE'){store.tasks=tasks().filter(x=>x.id!==t.id);}persistDemo();return {task:t};}
 if(p==='/api/people'&&method==='POST'){store.people.push({id:'u'+Date.now(),name:b.name,username:b.username,role:b.role||'resident'});persistDemo();return {people:store.people};}const roleMatch=p.match(/^\/api\/people\/([^/]+)\/role$/);if(roleMatch&&method==='PATCH'){const u=store.people.find(x=>x.id===roleMatch[1]);if(u)u.role=b.role;persistDemo();return {people:store.people};}
 return {ok:true};}
function nextDemoDate(iso,repeat){let d=iso?new Date(iso+'T12:00:00Z'):new Date();const step=()=>{if(repeat==='monthly')d.setUTCMonth(d.getUTCMonth()+1);else if(repeat==='quarterly')d.setUTCMonth(d.getUTCMonth()+3);else if(repeat==='yearly')d.setUTCFullYear(d.getUTCFullYear()+1);else d.setUTCDate(d.getUTCDate()+({daily:1,weekly:7,biweekly:14}[repeat]||7));};step();while(d<new Date())step();return d.toISOString().slice(0,10);}
