async function action(name,el){if(await featureAction(name,el))return;if(await finAction(name,el))return;if(name==='toggle-day'){const u=people().find(x=>x.id===el.dataset.person);if(!u)return;const d=Number(el.dataset.day);const days=new Set(u.accessDays||[]);days.has(d)?days.delete(d):days.add(d);const r=await api(`/api/people/${u.id}/schedule`,'PATCH',{accessDays:[...days]});if(r.people)store.people=r.people;render();toast(days.size?'Dias de acesso atualizados.':'Acesso em todos os dias.');return;}
if(name==='person-deactivate'){const u=people().find(x=>x.id===el.dataset.id);if(!u)return;const n=tasks().filter(t=>t.assignedTo===u.id&&t.status!=='done').length;if(!await confirmDialog({title:`Desativar a conta de ${u.name}?`,message:`Deixa de conseguir entrar na app.${n?` ${n} ${n===1?'tarefa por concluir fica':'tarefas por concluir ficam'} por atribuir e ${n===1?'volta':'voltam'} se reativares a conta.`:''} O histórico mantém-se.`,confirmLabel:'Desativar',danger:true}))return;const r=await api(`/api/people/${u.id}/status`,'PATCH',{active:false});if(r.people)store.people=r.people;await reload();toast(u.name+': conta desativada.');return;}
if(name==='person-activate'){const u=people().find(x=>x.id===el.dataset.id);const r=await api(`/api/people/${el.dataset.id}/status`,'PATCH',{active:true});if(r.people)store.people=r.people;await reload();toast((u?.name||'Conta')+': conta reativada.'+(r.tasks?` ${r.tasks} ${r.tasks===1?'tarefa voltou':'tarefas voltaram'} a ser atribuídas.`:''));return;}
if(name==='profile-open'){moreOpen=false;quickCreateOpen=false;modal={type:'profile'};render();return;}if(name==='more-toggle'){moreOpen=!moreOpen;quickCreateOpen=false;render();if(moreOpen)document.querySelector('.more-sheet [role=menuitem]')?.focus();return;}if(name==='more-close'){moreOpen=false;render();return;}if(name==='photo-pick'){document.getElementById('photo-input')?.click();return;}if(name==='photo-remove'){await saveProfile({photo:null},'Fotografia removida.');return;}if(name==='quick-toggle'){moreOpen=false;quickCreateOpen=!quickCreateOpen;render();if(quickCreateOpen)document.querySelector('.quick-create-menu [role=menuitem]')?.focus();return;}if(name==='quick-close'){quickCreateOpen=false;render();document.querySelector('.floating-add')?.focus();return;}if(name==='quick-new'){const kind=el.dataset.kind;quickCreateOpen=false;if(kind==='task'||kind==='routine'){render();openTask(null,kind==='routine'?'routine':'project');return;}if(kind==='finance'){if(!canFinance())return;render();await openExpense();return;}render();openQuickCreate(kind);return;}if(name==='view-person-tasks'){page='tasks';personFilter=el.dataset.id;query='';tab='active';render();window.scrollTo(0,0);return;}if(name==='dismiss-followup'){el.closest('.completion-followup')?.remove();return;}if(name==='worklog-after'){const taskId=el.dataset.id;el.closest('.completion-followup')?.remove();page='worklogs';render();const form=document.querySelector('#worklog-form');if(form){form.elements.namedItem('taskId').value=taskId;form.querySelector('textarea')?.focus();}return;}if(name==='shopping-view'){shoppingView=el.dataset.view;render();return;}if(name==='advanced-task'){const el2=document.querySelector('#task-advanced');if(el2){el2.hidden=!el2.hidden;el.setAttribute('aria-expanded',String(!el2.hidden));}return;}if(name==='filter-toggle'){taskFiltersOpen=!taskFiltersOpen;render();return;}if(name==='clear-filters'){query='';personFilter='all';roomFilter='all';priorityFilter='all';statusFilter='all';timeMode=false;render();return;}if(name==='config-add'){const list=document.querySelector('.manager-list[data-list="'+el.dataset.list+'"]');if(!list)return;const count=list.children.length;const row=document.createElement('div');row.className='manager-item';const field=document.createElement('input');field.setAttribute('data-config-item',el.dataset.list);field.setAttribute('aria-label','Novo nome');field.maxLength=70;const remove=document.createElement('button');remove.type='button';remove.className='manager-remove';remove.textContent='×';remove.setAttribute('aria-label','Remover item');remove.dataset.action='config-remove';remove.dataset.list=el.dataset.list;if(el.dataset.list==='floors'){field.maxLength=40;field.setAttribute('aria-label','Novo piso');}if(el.dataset.list==='rooms'&&config().floors.length){const t=document.createElement('template');t.innerHTML=floorSelect('',count).trim();row.append(field,t.content.firstChild,remove);}else row.append(field,remove);list.appendChild(row);field.focus();return;}if(name==='config-remove'){el.closest('.manager-item')?.remove();return;}if(name==='shopping-toggle'){const x=shopping().find(x=>x.id===el.dataset.id);if(!x)return;try{await api('/api/shopping/'+x.id,'PATCH',{purchased:!x.purchased});await reload();}catch(e){toast(e.message);}return;}if(name==='shopping-delete'){const x=shopping().find(x=>x.id===el.dataset.id);if(!x)return;try{await api('/api/shopping/'+x.id,'DELETE',{});modal=null;await reload();}catch(e){toast(e.message);}return;}if(name==='time'){durationLimit=Number(el.dataset.min);timeMode=durationLimit>0;page='tasks';tab='active';render();return;}if(name==='toggle-subtask'){const t=tasks().find(x=>x.id===el.dataset.id);if(!t)return;const list=(t.subtasks||[]).map((x,i)=>i===Number(el.dataset.index)?{...x,done:!x.done}:x);try{await api('/api/tasks/'+t.id,'PATCH',{subtasks:list});await reload();}catch(e){toast(e.message);}return;}if(name==='toggle-week'){const t=tasks().find(x=>x.id===el.dataset.id);if(!t)return;try{await api('/api/tasks/'+t.id,'PATCH',{thisWeek:!t.thisWeek});await reload();}catch(e){toast(e.message);}return;}if(name==='nav'){quickCreateOpen=false;moreOpen=false;if(el.dataset.page==='finance'){if(!canFinance())return;if(financeData)refreshFinance().then(()=>{if(page==='finance'&&!modal)render();}).catch(e=>toast(e.message));}page=el.dataset.page;modal=null;query='';personFilter='all';roomFilter='all';priorityFilter='all';statusFilter='all';render();window.scrollTo(0,0);return;}
 if(name==='jump'){page='tasks';tab='active';query='';roomFilter='all';statusFilter='all';personFilter=el.dataset.jump==='mine'?store.user.id:'all';priorityFilter=el.dataset.jump==='urgent'?'P1':'all';render();window.scrollTo(0,0);return;}
 if(name==='open-all-rooms'){page='tasks';tab='active';query='';statusFilter='all';personFilter='all';priorityFilter='all';roomFilter='all';render();window.scrollTo(0,0);return;}if(name==='open-room'){page='tasks';tab='active';query='';statusFilter='all';personFilter='all';priorityFilter='all';roomFilter=el.dataset.room;render();window.scrollTo(0,0);return;}
 if(name==='tab'){tab=el.dataset.tab;render();return;}
 if(name==='tasks-clear-done'){const n=tasks().filter(t=>t.kind==='project'&&t.status==='done').length;if(!await confirmDialog({title:`Eliminar ${n} ${n===1?'tarefa concluída':'tarefas concluídas'}?`,message:'Saem definitivamente da lista. As rotinas não são afetadas e o histórico de conclusões mantém-se.',confirmLabel:'Eliminar',danger:true}))return;try{const r=demo?(()=>{const k=tasks().filter(t=>t.kind==='project'&&t.status==='done').length;store.tasks=tasks().filter(t=>!(t.kind==='project'&&t.status==='done'));persistDemo();return {removed:k};})():await api('/api/tasks/clear-done','POST',{});await reload();toast(`${r.removed} ${r.removed===1?'tarefa eliminada':'tarefas eliminadas'}.`);}catch(e){toast(e.message);}return;}
 if(name==='add'){openTask(null,page==='routines'?'routine':'project');return;}
 if(name==='edit'){openTask(el.dataset.id);return;}
 if(name==='close'){closeModal();return;}
 if(name==='refresh'){await reload();toast(offline?'Sem ligação ao servidor.':'Dados atualizados.');return;}
 if(name==='complete'){if(offline&&!demo)return toast('Sem ligação. Não é possível guardar agora.');let t=tasks().find(x=>x.id===el.dataset.id);if(!t)return;
 try{const wasDone=t.status==='done';if(wasDone)await api(`/api/tasks/${t.id}`,'PATCH',{status:'todo'});else await api(`/api/tasks/${t.id}/complete`,'POST',{});await reload();if(!wasDone&&t.kind==='project'){document.querySelector('.completion-followup')?.remove();const notice=document.createElement('div');notice.className='completion-followup';notice.innerHTML='<span>Tarefa concluída! Registar o tempo utilizado?</span><button class="button" data-action="worklog-after" data-id="'+esc(t.id)+'">Registar trabalho</button><button class="icon-btn followup-close" data-action="dismiss-followup" aria-label="Fechar">×</button>';document.body.append(notice);setTimeout(()=>{notice.classList.add('out');setTimeout(()=>notice.remove(),300);},10000);}const nt=tasks().find(x=>x.id===t.id);toast(t.status==='done'?'Tarefa reaberta.':t.kind==='routine'&&t.repeat!=='none'?(Array.isArray(nt?.rotation)&&nt.rotation.length>1&&nt.assignedTo?`Rotina feita! Da próxima vez: ${owner(nt.assignedTo).split(' ')[0]}.`:'Rotina feita! Próxima ocorrência agendada.'):'Mais uma tarefa concluída!');}catch(e){toast(e.message);}return;}
 if(name==='delete'){let t=tasks().find(x=>x.id===el.dataset.id);if(!t||!await confirmDialog({title:'Eliminar esta tarefa?',message:`«${t.title}» será eliminada definitivamente.`,confirmLabel:'Eliminar',danger:true}))return;try{await api(`/api/tasks/${t.id}`,'DELETE',{});modal=null;await reload();toast('Tarefa eliminada.');}catch(e){toast(e.message);}return;}
 if(name==='add-person'){modal={type:'person'};renderModal();return;}
 if(name==='password-self'||name==='password-admin'){modal={type:'password',admin:name==='password-admin'};renderModal();return;}
 if(name==='logout'){try{await api('/api/logout','POST',{});}catch{}try{localStorage.removeItem('casa-cache');}catch{}store={people:[],tasks:[],history:[],user:null};modal=null;renderAuth('login');return;}
 if(name==='reset-demo'){if(!await confirmDialog({title:'Repor a demonstração?',message:'Perdes todas as alterações feitas neste dispositivo.',confirmLabel:'Repor',danger:true}))return;localStorage.removeItem('casa-demo-1-7');store={};initDemo();modal=null;page='dashboard';render();toast('Demonstração reposta.');return;}
 if(name==='import'){
   if(!demo && store.user.role!=='admin')return toast('Apenas administradores podem importar.');
   const input=$('#casa-import-file');if(!input)return toast('Abre Definições para importar.');
   input.value='';input.onchange=async()=>{
     const file=input.files&&input.files[0];if(!file)return;
     try{
       const payload=JSON.parse(await file.text());
       if(!Array.isArray(payload.tasks))throw Error('O ficheiro não contém uma lista de tarefas válida.');
       if(!await confirmDialog({title:'Importar tarefas?',message:`Até ${payload.tasks.length} tarefas de «${file.name}». As repetidas serão ignoradas.`,confirmLabel:'Importar'}))return;
       if(demo){let n=0;const ids=new Set(store.tasks.map(t=>[t.title,t.room,t.kind].join('|')));for(const raw of payload.tasks){const key=[raw.title,raw.room,raw.kind].join('|');if(!raw.title||ids.has(key))continue;ids.add(key);store.tasks.push({...raw,id:'import-'+Date.now()+'-'+n++});}persistDemo();render();toast(`${n} tarefas importadas para a demonstração.`);return;}
       const result=await api('/api/import','POST',{tasks:payload.tasks});await reload();toast(`${result.imported} tarefas importadas; ${result.skipped} ignoradas.`);
     }catch(e){toast(e.message||'Falha ao importar.');}
   };input.click();return;
 }
 if(name==='export'){try{const s=await api('/api/export');const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`casa-em-dia-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Exportação iniciada.');}catch(e){toast(e.message);}return;}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='overlay'&&e.target!==b)return;e.preventDefault();action(b.dataset.action,b).catch(err=>toast(err.message));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(quickCreateOpen||moreOpen)){quickCreateOpen=false;moreOpen=false;render();}});document.addEventListener('change',e=>{if(!e.target.matches('[name=person-filter],[name=room-filter],[name=priority-filter]'))return;let n=e.target.name,v=e.target.value;if(n==='person-filter')personFilter=v;if(n==='room-filter')roomFilter=v;if(n==='priority-filter')priorityFilter=v;let s=window.scrollY;render();window.scrollTo(0,s);});
let searchTimer;document.addEventListener('input',e=>{if(e.target.name!=='search')return;const pos=e.target.selectionStart;query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{let s=window.scrollY;render();let inp=$('[name=search]');if(inp){inp.focus();inp.setSelectionRange(pos,pos);}window.scrollTo(0,s);},180);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal)closeModal();});
