// Puxar para atualizar (ecrãs táteis): puxar no topo da página → largar → atualizar.
(function pullToRefresh(){
 if(!('ontouchstart' in window))return;
 const THRESHOLD=72,MAX=112;let startY=null,dist=0,busy=false;
 const el=document.createElement('div');el.className='ptr';el.setAttribute('role','status');el.setAttribute('aria-live','polite');
 el.innerHTML=ico('refresh','ptr-icon')+'<span class="ptr-text">Puxar para atualizar</span>';document.body.appendChild(el);
 const text=el.querySelector('.ptr-text'),icon=el.querySelector('.ptr-icon');
 const show=(d)=>{el.style.transform=`translate(-50%,${d-56}px)`;el.style.opacity=String(Math.min(1,d/40));icon.style.transform=`rotate(${d*3}deg)`;};
 const hide=()=>{el.classList.add('ptr-settle');el.style.transform='translate(-50%,-56px)';el.style.opacity='0';setTimeout(()=>{el.classList.remove('ptr-settle','ptr-loading');text.textContent='Puxar para atualizar';},260);};
 const blocked=t=>modal||quickCreateOpen||!store.user||t.closest('.tab-nav,.more-sheet,input,textarea,select,.modal,.quick-create-menu');
 window.addEventListener('touchstart',e=>{if(busy||window.scrollY>0||e.touches.length!==1||blocked(e.target)){startY=null;return;}startY=e.touches[0].clientY;dist=0;},{passive:true});
 window.addEventListener('touchmove',e=>{if(startY===null||busy)return;const dy=e.touches[0].clientY-startY;if(dy<=0||window.scrollY>0){dist=0;show(0);return;}
  dist=Math.min(MAX,dy*0.5);if(e.cancelable)e.preventDefault();show(dist);text.textContent=dist>=THRESHOLD?'Largar para atualizar':'Puxar para atualizar';el.classList.toggle('ptr-ready',dist>=THRESHOLD);},{passive:false});
 window.addEventListener('touchend',async()=>{if(startY===null||busy)return;startY=null;el.classList.remove('ptr-ready');
  if(dist<THRESHOLD){hide();return;}
  busy=true;el.classList.add('ptr-settle','ptr-loading');show(THRESHOLD);text.textContent='A atualizar…';
  const t0=Date.now();await reload();await new Promise(r=>setTimeout(r,Math.max(0,600-(Date.now()-t0))));
  text.textContent=offline?'Sem ligação ao servidor':'Atualizado';el.classList.remove('ptr-loading');
  setTimeout(()=>{hide();busy=false;},700);});
 window.addEventListener('touchcancel',()=>{if(!busy){startY=null;hide();}});
})();
